target.css:
:root {
  --ink: #26324a;
  --muted: #68758a;
  --paper: #fffdf7;
  --line: #dce2eb;
  --violet: #6557c9;
  --violet-soft: #eeecff;
  --mint: #dff4e9;
  --mint-ink: #217451;
  --yellow: #f7c95d;
}

.job-card {
  width: 480px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.job-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 16px 18px 13px;
  border-bottom: 1px solid var(--line);
}

.press-mark,
.document-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  color: var(--violet);
  background: var(--violet-soft);
  font-weight: 800;
}

.press-mark {
  width: 36px;
  height: 36px;
  border-radius: 11px;
  font-size: 22px;
}

.heading-copy {
  flex: 1;
  min-width: 0;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 18px;
  line-height: 1.15;
}

.status {
  padding: 5px 9px;
  border-radius: 999px;
  color: var(--mint-ink);
  background: var(--mint);
  font-size: 12px;
  font-weight: 700;
}

.job-summary {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
}

.document-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  font-size: 20px;
}

h2 {
  margin-bottom: 3px;
  font-size: 15px;
  line-height: 1.2;
}

.job-summary p,
.operator {
  color: var(--muted);
  font-size: 13px;
}

.job-details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0 18px;
  border: 1px solid var(--line);
  border-radius: 10px;
}

.detail {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 9px 12px;
}

.detail + .detail {
  border-left: 1px solid var(--line);
}

.detail span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.detail strong {
  font-size: 15px;
}

.job-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 14px;
  padding: 12px 18px;
  background: var(--violet-soft);
}

.action {
  border: 0;
  border-radius: 8px;
  padding: 8px 11px;
  color: var(--paper);
  background: var(--violet);
  font-size: 13px;
  font-weight: 700;
}

.action span {
  margin-left: 5px;
  color: var(--yellow);
  font-size: 16px;
}

